-- Kazakhstan deep-dive + milestone ES/DE/FR translations, completing 440
-- (deep-dive content) and 438 (milestones) against their English content.
-- This is a SEPARATE migration file, so every deep-dive translation row
-- looks up its parent row via a JOIN on stable identifying columns
-- (country code / section / sort_order), never via (SELECT MAX(id) ...).
-- milestone_translations has a natural PK on (milestone_id, lang), so
-- those rows are plain INSERT OR IGNORE statements keyed on the
-- hardcoded milestone id strings from 438 -- no JOIN needed. INSERT OR
-- IGNORE throughout. Every proper noun (IS ESF, ИС ЭСФ, NUC RK, Adilet),
-- law/order number (Order No. 370, Order No. 629, Law No. 214-VIII, Law
-- No. 120-VI, Law No. 235-V, Government Resolution No. 818), article
-- number (Art. 207-209, Art. 280-1), URL, and figure (MRP, KZT amounts,
-- percentages) is preserved unchanged from the English source; only the
-- surrounding prose is translated. Sourcing caveats ("not independently
-- confirmed", "plausible, not confirmed", etc.) are translated but kept
-- exactly as hedged as the English -- never softened or dropped.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es',
  'Régimen maduro de clearance centralizado (CTC): la facturación electrónica B2B obligatoria está vigente desde 2019 a través de la plataforma estatal IS ESF, ampliada a la cobertura universal de contribuyentes del IVA y a 12 categorías de no contribuyentes del IVA desde el 1 de enero de 2026 en virtud de un Código Tributario completamente nuevo',
  'Esta página de análisis refleja las disposiciones del Código Tributario de Kazajistán y sus órdenes de aplicación, confirmadas a través del propio sitio del Comité Estatal de Ingresos (kgd.gov.kz) y de la base de datos jurídica Adilet, junto con fuentes secundarias/sectoriales de buena reputación cuando no fue posible recuperar de forma independiente las páginas primarias, con fecha de principios de agosto de 2026, y se ofrece a título informativo general, no como asesoría legal o tributaria. Confirme los requisitos vigentes directamente con el Comité Estatal de Ingresos de Kazajistán, los canales de soporte propios de la plataforma IS ESF, o un asesor fiscal/legal kazajo antes de basar en esta página sus decisiones de cumplimiento.',
  'El sistema IS ESF de Kazajistán (Sistema de Información de Facturas Electrónicas) se lanzó el 1 de julio de 2014 con carácter puramente voluntario. Se volvió obligatorio para todos los contribuyentes registrados a efectos del IVA desde el 1 de enero de 2019, en virtud del Código Tributario de 2017 implementado mediante la Orden N.º 370. Un Código Tributario completamente nuevo (Ley N.º 214-VIII, firmada el 18 de julio de 2025) entró en vigor el 1 de enero de 2026, recodificando el mandato y ampliándolo a aproximadamente una docena de categorías de no contribuyentes del IVA, junto con la reducción del umbral de registro del IVA y un aumento de la tasa estándar del IVA.',
  'Una factura electrónica kazaja conforme es un XML estructurado, presentado exclusivamente a través de la plataforma estatal IS ESF bajo una firma electrónica cualificada emitida por una Autoridad Nacional de Certificación acreditada (NUC RK). La transmisión sigue un modelo de clearance con prevalidación en tiempo real (CTC): cada factura se presenta ante IS ESF y es validada por esta, recibiendo un número de registro único, antes de volverse visible y válida para el comprador -- no se permite el intercambio directo entre pares fuera de IS ESF.',
  'El mandato de facturación electrónica se aplica a todo contribuyente registrado a efectos del IVA, además de (desde el 1 de enero de 2026) aproximadamente una docena de categorías específicamente enumeradas no registradas a efectos del IVA, incluidos agentes comisionistas y transitarios, representantes aduaneros y transportistas, contribuyentes bajo régimen tributario simplificado, vendedores médicos y farmacéuticos, bufetes de abogados, importadores y participantes en el módulo de trazabilidad de mercancías "Almacén Virtual". No existe un umbral de ingresos sobre la propia obligación de facturación electrónica, aunque el umbral de registro del IVA que determina indirectamente quién se convierte en contribuyente del IVA se redujo a 10.000 MRP (aproximadamente KZT 40-43 millones de facturación anual) para 2026.',
  'La mayoría de las empresas registradas a efectos del IVA que comercian en Kazajistán ya tienen una obligación vigente de facturación electrónica en IS ESF -- el mandato central está en vigor desde 2019. El trabajo más reciente es la ampliación de alcance del 1 de enero de 2026: las categorías de no contribuyentes del IVA recién cubiertas deben comprobar si su actividad ahora requiere facturación electrónica, y todos los contribuyentes del IVA deben verificar su condición de registro frente al nuevo umbral reducido de 10.000 MRP y prepararse para los nuevos campos de factura y el flujo de confirmación del comprador de la Orden N.º 629.',
  'Kazajistán hace cumplir la facturación electrónica a través del artículo 280-1 del Código de Infracciones Administrativas, con multas escalonadas según el tamaño de la empresa y la reincidencia; un mecanismo de crédito del IVA de 2026 hace, por separado, que el IVA solo sea recuperable cuando la factura electrónica subyacente se confirme activamente dentro de IS ESF antes de presentar la declaración del IVA.',
  'Kazajistán exige la facturación electrónica a todos los contribuyentes registrados a efectos del IVA desde el 1 de enero de 2019, a través de la plataforma estatal de clearance IS ESF. Desde el 1 de enero de 2026, un Código Tributario completamente nuevo amplió el mandato a aproximadamente una docena de categorías de no contribuyentes del IVA (agentes comisionistas, representantes aduaneros, vendedores médicos/farmacéuticos, bufetes de abogados, importadores, entre otros), junto con la reducción del umbral de registro del IVA (10.000 MRP) y un aumento de la tasa estándar del IVA (16 %). Un mecanismo independiente de 2026 vincula la elegibilidad del crédito del IVA directamente con la confirmación activa de la factura electrónica dentro de IS ESF.',
  '🇰🇿'
FROM countries WHERE code = 'KZ';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 ene 2019', 'La facturación electrónica se vuelve obligatoria para todos los contribuyentes registrados a efectos del IVA' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 ene 2026', 'El mandato se amplía a ~12 categorías de no contribuyentes del IVA en virtud del nuevo Código Tributario' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '10.000 MRP', 'Nuevo umbral de registro del IVA para 2026 (~KZT 40-43 millones de facturación), frente a los ~20.000 MRP anteriores' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '16 %', 'Nueva tasa estándar del IVA desde 2026, frente al 12 % anterior' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '2014', 'IS ESF se lanza como proyecto piloto voluntario -- 12 años de historia para cuando llega la ampliación de 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y modelo de transmisión', '[["Formato de la factura", "XML estructurado, presentado exclusivamente a través de la plataforma estatal IS ESF"], ["Modelo de transmisión", "Clearance con prevalidación en tiempo real (CTC) -- IS ESF valida y asigna un número de registro antes de que la factura llegue al comprador"], ["Firma digital", "Firma electrónica cualificada mediante un certificado de una Autoridad Nacional de Certificación acreditada (NUC RK)"], ["Intercambio entre pares", "No permitido -- toda factura debe pasar por IS ESF"]]', 'Si IS ESF acepta únicamente XML sin ningún formato alternativo es un dato obtenido solo a través de un único resumen informativo secundario generado por IA en esta ronda de investigación, no verificado de forma independiente frente al texto primario de la Orden N.º 629/Código Tributario -- trátese como plausible, no confirmado.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Evolución del marco jurídico', '[["2014-2018", "Reglas voluntarias en virtud de las Resoluciones Gubernamentales N.º 818 y N.º 573, y después la Orden N.º 270 conforme al Código Tributario de 2018"], ["2019-2025", "La Orden N.º 370 (22 de abril de 2019, retroactiva al 1 de enero de 2019) rige la era obligatoria, modificada en repetidas ocasiones mediante la Orden N.º 1321 (26 de diciembre de 2023)"], ["Desde 2026", "El nuevo Código Tributario (Ley N.º 214-VIII) junto con la Orden N.º 629 (28 de octubre de 2025) sustituyen por completo el marco anterior"]]', 'La página exacta de la base de datos jurídica Adilet correspondiente a la Orden N.º 629 no pudo recuperarse de forma independiente en esta ronda de investigación (errores de robots/SSL en todos los intentos) -- su número de orden y fecha están corroborados por dos fuentes secundarias independientes del sector, pero aún se recomienda la verificación directa de la fuente primaria.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Quién debe emitir facturas electrónicas', '[["Contribuyentes registrados a efectos del IVA", "Requisito universal desde el 1 de enero de 2019 (Código Tributario de 2017); recodificado en el art. 207 del nuevo Código Tributario desde 2026"], ["Categorías de no contribuyentes del IVA (desde 2026)", "~12 categorías conforme a los arts. 208-209: agentes comisionistas/transitarios, representantes aduaneros/transportistas, contribuyentes bajo régimen simplificado, vendedores médicos/farmacéuticos, bufetes de abogados, importadores, participantes del Almacén Virtual, y otros"], ["Excluidos explícitamente", "Particulares que venden bienes personales; profesionales privados/empresarios individuales que actúan en esa condición; la mayoría de las ventas minoristas mediante caja registradora (con excepciones para bienes sujetos a impuestos especiales/importados/enumerados)"], ["Umbral de ingresos", "Ninguno sobre la propia obligación de facturación electrónica, pero el umbral subyacente de registro del IVA se redujo a 10.000 MRP para 2026"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de clearance', 'Una factura conforme con IS ESF pasa por la siguiente secuencia:', 'Solo una factura que IS ESF haya validado y a la que haya asignado un número de registro es legalmente válida para el comprador -- la entrega directa fuera de la plataforma no tiene ningún efecto.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Generar el XML estructurado y aplicar una firma digital cualificada de la NUC RK' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Presentarla ante la plataforma estatal IS ESF para su prevalidación' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'IS ESF valida la estructura y el contenido, y asigna un número de registro único' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'La factura validada se vuelve visible y legalmente válida para el comprador' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Desde 2026: la elegibilidad del comprador para el crédito del IVA depende de la confirmación activa de la factura dentro de IS ESF antes de presentar la declaración del IVA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚠️ Sanciones conforme al artículo 280-1 del Código de Infracciones Administrativas', NULL, NULL, 'Kazajistán sanciona las infracciones de facturación electrónica en virtud del artículo 280-1 del Código de Infracciones Administrativas (código base: Ley N.º 235-V, 5 de julio de 2014). La primera infracción por no emitir o por emitir con retraso conlleva una advertencia; las infracciones reincidentes dentro de un año conllevan multas escalonadas según el tamaño de la empresa -- aproximadamente 40-150 MRP por reincidencia en la no emisión (pequeña/mediana/gran empresa), y 20-100 MRP por reincidencia en la emisión tardía. La falta de los documentos de exportación que deben acompañar la factura conlleva una multa fija de 50 MRP en la primera infracción, 100 MRP en caso de reincidencia. Al valor del MRP de 2026 (KZT 4.325), una multa de 40 MRP para una pequeña empresa equivale aproximadamente a KZT 173.000. Estas cifras están corroboradas por dos sitios agregadores jurídicos secundarios independientes con estructuras coincidentes, pero ninguno es el propio texto estatutario primario de Adilet de Kazajistán -- trátense como plausibles a la espera de una verificación directa.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '💳 Crédito del IVA vinculado a la confirmación de la factura electrónica', NULL, NULL, 'Desde 2026, un nuevo mecanismo vincularía, según se informa, la elegibilidad del crédito del IVA directamente con el cumplimiento de la facturación electrónica: el IVA soportado solo puede acreditarse cuando la factura electrónica específica se confirme activamente dentro de IS ESF antes de presentar la declaración del IVA. Por separado, una fuente secundaria describe otro mecanismo de aplicación de 2026 que permitiría la suspensión temporal del acceso de un contribuyente a IS ESF por notificaciones del sistema no atendidas, lo que bloquearía en la práctica por completo la facturación -- este mecanismo de suspensión no está confirmado de forma independiente frente a una cita primaria del Código Tributario y debe tratarse como no verificado.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔍 Lo que no pudimos confirmar', NULL, NULL, 'Se señalan cuatro elementos de esta ronda de investigación en lugar de presentarlos como hechos establecidos: (1) el dominio público exacto y actual del portal de IS ESF -- los resultados de búsqueda arrojaron tanto una referencia a "esf.gov.kz" como lo que parece ser un dominio clon de phishing no relacionado, por lo que en esta página no se cita ninguna URL de portal sin verificar; (2) si IS ESF acepta realmente solo XML, sin ningún formato alternativo, dato obtenido únicamente a través de un único resumen informativo generado por IA; (3) los plazos exactos en días para la emisión y la excepción de factura en papel por caída del sistema, con la misma salvedad de fuente única; (4) si existe una ola independiente y con fecha propia de facturación electrónica obligatoria para "bienes de riesgo" anterior a 2019, previa al mandato general de 2019 -- no se pudo encontrar ninguna fecha obtenida de forma independiente para esto, por lo que no se incluye tal hito en esta página.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme su condición de contribuyente del IVA y su registro en IS ESF', 'La facturación electrónica es obligatoria para todos los contribuyentes registrados a efectos del IVA en Kazajistán desde el 1 de enero de 2019 -- confirme que su empresa está registrada para el acceso a IS ESF y que dispone de un certificado digital NUC RK válido.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Si no está registrado a efectos del IVA, revise las categorías de no contribuyentes del nuevo Código Tributario', 'Desde el 1 de enero de 2026, aproximadamente una docena de categorías no registradas a efectos del IVA (agentes comisionistas/transitarios, representantes aduaneros, contribuyentes bajo régimen simplificado, vendedores médicos/farmacéuticos, bufetes de abogados, importadores, y otros) también deben emitir facturas electrónicas -- revise los artículos 208-209 para comprobar si su actividad está ahora dentro del alcance.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Actualice el software de facturación para los nuevos campos y el flujo de confirmación del comprador de la Orden N.º 629', 'El nuevo formulario y reglamento de factura electrónica, vigentes desde el 1 de enero de 2026, añaden campos (fecha de registro del IVA, códigos del Catálogo Nacional de Productos, categorías de proveedor abogado/no residente) y exigen la confirmación obligatoria del comprador para las facturas corregidas o anuladas.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Vuelva a comprobar su registro del IVA frente al umbral reducido de 10.000 MRP', 'El umbral de registro del IVA para 2026 se redujo a aproximadamente KZT 40-43 millones de facturación anual (desde alrededor de KZT 73-75 millones) -- las empresas cercanas al antiguo umbral deben volver a comprobar si ahora están obligadas a registrarse y, por lo tanto, a emitir facturas electrónicas.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Verifique el dominio actual del portal de IS ESF directamente con el Comité Estatal de Ingresos', 'Los resultados de búsqueda de la plataforma IS ESF arrojaron dominios contradictorios/no oficiales junto con el genuino -- confirme la URL de inicio de sesión correcta y actual a través de la propia sección de facturación electrónica de kgd.gov.kz, en lugar de un resultado de búsqueda, antes de introducir cualquier credencial.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Comité Estatal de Ingresos -- sección de Facturas Electrónicas (IS ESF)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KZ' AND pt.sort_order = 0;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-voluntary-2014', 'es',
  'Se lanza la facturación electrónica voluntaria (ИС ЭСФ)',
  'El sistema de información de facturas electrónicas de Kazajistán (ИС ЭСФ) entró en funcionamiento el 1 de julio de 2014 con carácter puramente voluntario, en virtud de la Resolución Gubernamental N.º 818 (23 de julio de 2014), que estableció las reglas originales para el formato, la emisión, la transmisión, la recepción, el registro y el almacenamiento de las facturas electrónicas. Esto se basó en el artículo 263 del entonces vigente Código Tributario de 2008 y marcó el inicio de un despliegue que no se volvería obligatorio hasta cinco años después.',
  '["No se requiere ninguna acción en esta etapa -- la participación era opcional.","Las empresas que deseaban adelantarse podían inscribirse voluntariamente a través del Comité Estatal de Ingresos (kgd.gov.kz)."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-b2b-mandatory-2019', 'es',
  'La facturación electrónica se vuelve obligatoria para todos los contribuyentes del IVA',
  'Desde el 1 de enero de 2019, todo contribuyente registrado a efectos del IVA en Kazajistán quedó obligado a emitir facturas electrónicas por la venta de bienes, obras y servicios, en virtud del Código Tributario de 2017 (Ley N.º 120-VI), implementado mediante la Orden N.º 370 (22 de abril de 2019, aplicada retroactivamente desde el 1 de enero de 2019). Kazajistán opera un modelo de clearance de prevalidación en tiempo real: cada factura se presenta ante la plataforma central IS ESF y es validada por esta antes de ser visible para el comprador, comparable a los sistemas de clearance utilizados en Colombia y Argentina.',
  '["Regístrese para obtener acceso a IS ESF y obtenga un certificado digital de la Autoridad Nacional de Certificación (NUC RK).","Confirme que su software de facturación presenta cada factura de venta ante IS ESF para su prevalidación antes de la entrega al comprador.","Conserve las facturas validadas y su registro de aceptación de IS ESF conforme a las normas de conservación documental de Kazajistán."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-newtaxcode-2025', 'es',
  'Se promulga el nuevo Código Tributario',
  'La Ley N.º 214-VIII (firmada el 18 de julio de 2025) promulgó un Código Tributario completamente nuevo, con entrada en vigor el 1 de enero de 2026, que sustituye al Código Tributario de 2017 (N.º 120-VI) bajo el cual había operado el mandato de facturación electrónica de 2019. El nuevo código recodifica la obligación de facturación electrónica en los artículos 207-209 y es el instrumento legislativo que da lugar a la ampliación del alcance y a la reducción del umbral del IVA que entran en vigor el 1 de enero de 2026. Nota: esta fuente es un sitio espejo de textos legales, no directamente adilet.zan.kz -- adilet.zan.kz bloqueó la recuperación automatizada de esta página en esta sesión y debe consultarse directamente antes de tratar la cita como plenamente verificada como fuente primaria.',
  '["Revise los artículos 207-209 del nuevo Código Tributario para conocer las categorías recodificadas de facturación electrónica antes de la entrada en vigor el 1 de enero de 2026."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-order629-2025', 'es',
  'Se aprueba el nuevo formulario y reglamento de factura electrónica (Orden N.º 629)',
  'La Orden N.º 629 del Ministro de Finanzas (28 de octubre de 2025) aprobó un nuevo formulario y conjunto de reglas para la factura electrónica, en sustitución de la Orden N.º 370 y con entrada en vigor el 1 de enero de 2026 junto con el nuevo Código Tributario. Añade nuevos campos a la factura (fecha de registro del IVA, códigos del Catálogo Nacional de Productos, categorías de proveedor abogado/no residente), exige identificación biométrica para el registro e introduce la confirmación obligatoria del comprador para las facturas corregidas o anuladas. Obtenida a través de dos sitios secundarios independientes del sector (acsour.kz, pro1c.kz) que coinciden en el número y la fecha de la orden; la página correspondiente de Adilet como fuente primaria no pudo recuperarse de forma independiente en esta sesión y debe verificarse directamente antes de basarse en ella con mayor confianza.',
  '["Actualice el software de facturación antes del 1 de enero de 2026 para incorporar los nuevos campos obligatorios y el flujo de confirmación del comprador introducidos por la Orden N.º 629."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-scope-expansion-2026', 'es',
  'El mandato se amplía: cobertura universal de contribuyentes del IVA más 12 categorías de no contribuyentes del IVA',
  'Desde el 1 de enero de 2026, los artículos 207-209 del nuevo Código Tributario confirman la cobertura universal de la facturación electrónica para todos los contribuyentes del IVA y amplían la obligación a aproximadamente una docena de categorías no registradas a efectos del IVA -- agentes comisionistas y transitarios, representantes aduaneros y transportistas, contribuyentes bajo el régimen tributario simplificado, vendedores médicos/farmacéuticos, bufetes de abogados, importadores y participantes en el módulo de trazabilidad "Almacén Virtual", entre otros. Esto coincide con la reducción del umbral de registro del IVA (10.000 MRP, aproximadamente KZT 40-43 millones de facturación anual, frente a los aproximadamente 20.000 MRP anteriores) y con un aumento de la tasa estándar del IVA al 16 %, ambos factores que amplían indirectamente la población ahora sujeta a la facturación electrónica.',
  '["Empresas no registradas a efectos del IVA: verifiquen las categorías del art. 208 del nuevo Código Tributario para comprobar si su actividad (comisión/transporte, servicios aduaneros, régimen simplificado, ventas médicas/farmacéuticas, servicios jurídicos, importaciones, mercancías rastreadas) requiere ahora facturación electrónica.","Vuelvan a comprobar su condición de registro del IVA frente al nuevo y menor umbral de 10.000 MRP para 2026."]'
);

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de',
  'Ausgereiftes zentrales Freigabesystem (CTC): die verpflichtende B2B-E-Rechnungsstellung ist seit 2019 über die staatliche IS-ESF-Plattform in Kraft, ausgeweitet auf die universelle Erfassung mehrwertsteuerpflichtiger Personen sowie 12 nicht-mehrwertsteuerpflichtige Kategorien ab dem 1. Januar 2026 im Rahmen eines vollständig neuen Steuergesetzbuchs',
  'Diese Analyseseite spiegelt die Bestimmungen des kasachischen Steuergesetzbuchs und die zugehörigen Durchführungserlasse wider, wie sie über die eigene Website des Staatlichen Einnahmenkomitees (kgd.gov.kz) und die Rechtsdatenbank Adilet bestätigt wurden, ergänzt durch angesehene sekundäre/branchenbezogene Quellen dort, wo primäre Seiten nicht unabhängig abgerufen werden konnten, mit Stand Anfang August 2026, und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt beim Staatlichen Einnahmenkomitee Kasachstans, den eigenen Support-Kanälen der IS-ESF-Plattform oder einem kasachischen Steuer-/Rechtsberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.',
  'Kasachstans IS ESF (Informationssystem für elektronische Rechnungen) startete am 1. Juli 2014 auf rein freiwilliger Basis. Es wurde für alle mehrwertsteuerpflichtig registrierten Steuerpflichtigen ab dem 1. Januar 2019 verpflichtend, gemäß dem Steuergesetzbuch von 2017, umgesetzt durch den Erlass Nr. 370. Ein vollständig neues Steuergesetzbuch (Gesetz Nr. 214-VIII, unterzeichnet am 18. Juli 2025) trat am 1. Januar 2026 in Kraft, kodifizierte das Mandat neu und weitete es auf rund ein Dutzend nicht-mehrwertsteuerpflichtige Kategorien aus, zusammen mit einer gesenkten MwSt-Registrierungsschwelle und einem höheren MwSt-Regelsatz.',
  'Eine konforme kasachische E-Rechnung ist ein strukturiertes XML-Dokument, das ausschließlich über die staatliche IS-ESF-Plattform unter einer qualifizierten elektronischen Signatur eingereicht wird, die von einer akkreditierten Nationalen Zertifizierungsstelle (NUC RK) ausgestellt wurde. Die Übermittlung folgt einem Echtzeit-Vorabvalidierungsmodell (CTC): Jede Rechnung wird bei IS ESF eingereicht und von diesem validiert, wobei sie eine eindeutige Registrierungsnummer erhält, bevor sie für den Käufer sichtbar und gültig wird -- ein direkter Peer-to-Peer-Austausch außerhalb von IS ESF ist nicht zulässig.',
  'Die E-Rechnungspflicht gilt für jeden mehrwertsteuerpflichtig registrierten Steuerpflichtigen sowie (ab dem 1. Januar 2026) für rund ein Dutzend eigens aufgeführter, nicht mehrwertsteuerpflichtig registrierter Kategorien, darunter Kommissionäre und Spediteure, Zollvertreter und Frachtführer, Steuerpflichtige im vereinfachten Steuerregime, medizinische und pharmazeutische Verkäufer, Anwaltskanzleien, Importeure sowie Teilnehmer am Rückverfolgbarkeitsmodul „Virtuelles Lager". Für die E-Rechnungspflicht selbst besteht keine Umsatzschwelle, allerdings wurde die MwSt-Registrierungsschwelle, die indirekt bestimmt, wer mehrwertsteuerpflichtig wird, für 2026 auf 10.000 MRP (etwa KZT 40-43 Millionen Jahresumsatz) gesenkt.',
  'Die meisten mehrwertsteuerpflichtig registrierten Unternehmen, die in Kasachstan Handel treiben, haben bereits eine bestehende IS-ESF-E-Rechnungspflicht -- das Kernmandat gilt seit 2019. Die neuere Aufgabe ist die Ausweitung des Anwendungsbereichs zum 1. Januar 2026: neu erfasste nicht-mehrwertsteuerpflichtige Kategorien sollten prüfen, ob ihre Tätigkeit nun eine E-Rechnungspflicht auslöst, und alle Mehrwertsteuerpflichtigen sollten ihren Registrierungsstatus anhand der gesenkten Schwelle von 10.000 MRP überprüfen und sich auf die neuen Rechnungsfelder und den Käuferbestätigungs-Workflow des Erlasses Nr. 629 vorbereiten.',
  'Kasachstan setzt die Einhaltung der E-Rechnungspflicht über Artikel 280-1 des Gesetzbuchs über Ordnungswidrigkeiten durch, mit gestaffelten Bußgeldern je nach Unternehmensgröße und Wiederholungsstatus; ein separater MwSt-Anrechnungsmechanismus von 2026 macht die MwSt zudem nur dann erstattungsfähig, wenn die zugrunde liegende E-Rechnung vor Abgabe der MwSt-Erklärung aktiv innerhalb von IS ESF bestätigt wurde.',
  'Kasachstan verlangt seit dem 1. Januar 2019 die E-Rechnungsstellung für alle mehrwertsteuerpflichtig registrierten Steuerpflichtigen über die staatliche IS-ESF-Freigabeplattform. Ab dem 1. Januar 2026 weitete ein vollständig neues Steuergesetzbuch das Mandat auf rund ein Dutzend nicht-mehrwertsteuerpflichtige Kategorien aus (Kommissionäre, Zollvertreter, medizinische/pharmazeutische Verkäufer, Anwaltskanzleien, Importeure und mehr), zusammen mit einer gesenkten MwSt-Registrierungsschwelle (10.000 MRP) und einem höheren MwSt-Regelsatz (16 %). Ein separater Mechanismus von 2026 knüpft die Berechtigung zur MwSt-Anrechnung direkt an die aktive Bestätigung der E-Rechnung innerhalb von IS ESF.',
  '🇰🇿'
FROM countries WHERE code = 'KZ';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2019', 'Die E-Rechnungsstellung wird für alle mehrwertsteuerpflichtig registrierten Steuerpflichtigen verpflichtend' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2026', 'Das Mandat wird im Rahmen des neuen Steuergesetzbuchs auf ~12 nicht-mehrwertsteuerpflichtige Kategorien ausgeweitet' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '10.000 MRP', 'Neue MwSt-Registrierungsschwelle für 2026 (~KZT 40-43 Millionen Umsatz), gegenüber zuvor ~20.000 MRP' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '16 %', 'Neuer MwSt-Regelsatz ab 2026, gegenüber zuvor 12 %' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '2014', 'IS ESF startet als freiwilliges Pilotprojekt -- bis zur Ausweitung 2026 liegen 12 Jahre Geschichte' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Übermittlungsmodell', '[["Rechnungsformat", "Strukturiertes XML, ausschließlich über die staatliche IS-ESF-Plattform eingereicht"], ["Übermittlungsmodell", "Echtzeit-Vorabvalidierung (CTC) -- IS ESF validiert und vergibt eine Registrierungsnummer, bevor die Rechnung den Käufer erreicht"], ["Digitale Signatur", "Qualifizierte elektronische Signatur mittels eines Zertifikats einer akkreditierten Nationalen Zertifizierungsstelle (NUC RK)"], ["Peer-to-Peer-Austausch", "Nicht zulässig -- jede Rechnung muss über IS ESF geleitet werden"]]', 'Ob IS ESF ausschließlich XML ohne alternatives Format akzeptiert, stammt in dieser Rechercherunde nur aus einem einzigen KI-zusammengefassten sekundären Briefing und wurde nicht unabhängig gegen den primären Text des Erlasses Nr. 629/des Steuergesetzbuchs abgeglichen -- als plausibel, nicht als bestätigt zu behandeln.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Entwicklung des Rechtsrahmens', '[["2014-2018", "Freiwillige Regeln gemäß den Regierungsbeschlüssen Nr. 818 und Nr. 573, danach der Erlass Nr. 270 unter dem Steuergesetzbuch von 2018"], ["2019-2025", "Der Erlass Nr. 370 (22. April 2019, rückwirkend zum 1. Januar 2019) regelt die verpflichtende Ära und wurde wiederholt durch den Erlass Nr. 1321 (26. Dezember 2023) geändert"], ["Ab 2026", "Das neue Steuergesetzbuch (Gesetz Nr. 214-VIII) zusammen mit dem Erlass Nr. 629 (28. Oktober 2025) ersetzen den bisherigen Rahmen vollständig"]]', 'Die genaue Adilet-Rechtsdatenbankseite zum Erlass Nr. 629 konnte in dieser Rechercherunde nicht unabhängig abgerufen werden (bei jedem Versuch Robots-/SSL-Fehler) -- Erlassnummer und Datum werden durch zwei unabhängige sekundäre Branchenquellen bestätigt, eine direkte Primärquellenverifizierung wird jedoch weiterhin empfohlen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer E-Rechnungen ausstellen muss', '[["Mehrwertsteuerpflichtig registrierte Steuerpflichtige", "Universelle Pflicht seit 1. Januar 2019 (Steuergesetzbuch von 2017); ab 2026 neu kodifiziert in Art. 207 des neuen Steuergesetzbuchs"], ["Nicht-mehrwertsteuerpflichtige Kategorien (ab 2026)", "~12 Kategorien gemäß Art. 208-209: Kommissionäre/Spediteure, Zollvertreter/Frachtführer, Steuerpflichtige im vereinfachten Regime, medizinische/pharmazeutische Verkäufer, Anwaltskanzleien, Importeure, Teilnehmer am Virtuellen Lager, und weitere"], ["Ausdrücklich ausgeschlossen", "Privatpersonen, die persönliches Eigentum verkaufen; private Praktiker/Einzelunternehmer, die in dieser Eigenschaft handeln; die meisten Einzelhandelsverkäufe über die Registrierkasse (mit Ausnahmen für verbrauchsteuerpflichtige/importierte/gelistete Waren)"], ["Umsatzschwelle", "Keine für die E-Rechnungspflicht selbst, aber die zugrunde liegende MwSt-Registrierungsschwelle sank für 2026 auf 10.000 MRP"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Freigabeprozess (Clearance-Flow)', 'Eine konforme IS-ESF-Rechnung durchläuft folgende Abfolge:', 'Nur eine Rechnung, die IS ESF validiert und mit einer Registrierungsnummer versehen hat, ist für den Käufer rechtlich gültig -- eine direkte Zustellung außerhalb der Plattform hat keine Wirkung.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Strukturiertes XML erzeugen und eine qualifizierte digitale NUC-RK-Signatur anbringen' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Bei der staatlichen IS-ESF-Plattform zur Vorabvalidierung einreichen' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'IS ESF validiert Struktur und Inhalt und vergibt eine eindeutige Registrierungsnummer' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Die validierte Rechnung wird für den Käufer sichtbar und rechtlich gültig' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Ab 2026: Die Berechtigung des Käufers zur MwSt-Anrechnung hängt von der aktiven Bestätigung der Rechnung innerhalb von IS ESF vor Abgabe der MwSt-Erklärung ab' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚠️ Sanktionen gemäß Artikel 280-1 des Gesetzbuchs über Ordnungswidrigkeiten', NULL, NULL, 'Kasachstan sanktioniert Verstöße gegen die E-Rechnungspflicht gemäß Artikel 280-1 des Gesetzbuchs über Ordnungswidrigkeiten (Grundgesetz: Gesetz Nr. 235-V, 5. Juli 2014). Beim ersten Verstoß gegen die Ausstellungspflicht oder bei verspäteter Ausstellung erfolgt eine Verwarnung; wiederholte Verstöße innerhalb eines Jahres ziehen nach Unternehmensgröße gestaffelte Bußgelder nach sich -- etwa 40-150 MRP bei wiederholter Nichtausstellung (kleine/mittlere/große Unternehmen) und 20-100 MRP bei wiederholter verspäteter Ausstellung. Fehlende Exportbegleitdokumente ziehen ein Pauschalbußgeld von 50 MRP beim ersten Verstoß nach sich, 100 MRP bei Wiederholung. Beim MRP-Wert von 2026 (KZT 4.325) entspricht ein Bußgeld von 40 MRP für ein kleines Unternehmen etwa KZT 173.000. Diese Zahlen werden durch zwei unabhängige sekundäre Rechtsaggregator-Websites mit übereinstimmender Struktur bestätigt, keine davon ist jedoch der eigene primäre Adilet-Gesetzestext Kasachstans -- als plausibel, aber noch nicht direkt verifiziert zu behandeln.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '💳 MwSt-Anrechnung an die Bestätigung der E-Rechnung geknüpft', NULL, NULL, 'Ab 2026 knüpft ein neuer Mechanismus Berichten zufolge die Berechtigung zur MwSt-Anrechnung direkt an die Einhaltung der E-Rechnungspflicht: Die Vorsteuer kann nur dann angerechnet werden, wenn die betreffende E-Rechnung vor Abgabe der MwSt-Erklärung aktiv innerhalb von IS ESF bestätigt wurde. Getrennt davon beschreibt eine Sekundärquelle einen weiteren Durchsetzungsmechanismus für 2026, der eine vorübergehende Sperrung des IS-ESF-Zugangs eines Steuerpflichtigen bei unbeantworteten Systembenachrichtigungen erlauben würde, was die Rechnungsstellung faktisch vollständig blockieren würde -- dieser Sperrmechanismus ist nicht unabhängig anhand einer primären Fundstelle im Steuergesetzbuch bestätigt und sollte als unverifiziert behandelt werden.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔍 Was wir nicht bestätigen konnten', NULL, NULL, 'Vier Punkte werden aus dieser Rechercherunde als offen gekennzeichnet, statt als gesicherte Tatsache dargestellt: (1) die genaue aktuelle öffentliche IS-ESF-Portaldomain -- Suchergebnisse lieferten sowohl einen Verweis auf „esf.gov.kz" als auch eine offenbar nicht zugehörige Phishing-Klon-Domain, weshalb auf dieser Seite keine unverifizierte Portal-URL angegeben wird; (2) ob IS ESF tatsächlich ausschließlich XML akzeptiert, ohne alternatives Format, was nur aus einem einzigen KI-zusammengefassten Briefing stammt; (3) die genauen Fristtage für die Ausstellung und die Ausnahme für Papierrechnungen bei Systemausfall, mit demselben Einzelquellen-Vorbehalt; (4) ob eine eigenständige, separat datierte verpflichtende E-Rechnungswelle für „Risikowaren" vor 2019 existiert, die dem allgemeinen Mandat von 2019 vorausging -- hierfür konnte kein unabhängig belegtes Datum gefunden werden, weshalb auf dieser Seite kein entsprechender Meilenstein aufgeführt ist.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie Ihren MwSt-Status und Ihre IS-ESF-Registrierung', 'Die E-Rechnungsstellung ist seit dem 1. Januar 2019 für alle mehrwertsteuerpflichtig registrierten Steuerpflichtigen in Kasachstan verpflichtend -- bestätigen Sie, dass Ihr Unternehmen für den IS-ESF-Zugang registriert ist und über ein gültiges digitales NUC-RK-Zertifikat verfügt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Wenn Sie nicht mehrwertsteuerpflichtig registriert sind, prüfen Sie die nicht-mehrwertsteuerpflichtigen Kategorien des neuen Steuergesetzbuchs', 'Ab dem 1. Januar 2026 müssen auch rund ein Dutzend nicht mehrwertsteuerpflichtig registrierte Kategorien (Kommissionäre/Spediteure, Zollvertreter, Steuerpflichtige im vereinfachten Regime, medizinische/pharmazeutische Verkäufer, Anwaltskanzleien, Importeure und weitere) E-Rechnungen ausstellen -- prüfen Sie die Artikel 208-209, um festzustellen, ob Ihre Tätigkeit nun erfasst ist.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Aktualisieren Sie die Rechnungssoftware für die neuen Felder und den Käuferbestätigungs-Workflow des Erlasses Nr. 629', 'Das neue E-Rechnungsformular und die neuen Vorschriften, die ab dem 1. Januar 2026 gelten, fügen Felder hinzu (MwSt-Registrierungsdatum, Codes des Nationalen Produktkatalogs, Kategorien für Anwalts-/gebietsfremde Lieferanten) und verlangen eine verpflichtende Käuferbestätigung für korrigierte oder stornierte Rechnungen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Überprüfen Sie Ihre MwSt-Registrierung erneut anhand der gesenkten Schwelle von 10.000 MRP', 'Die MwSt-Registrierungsschwelle für 2026 sank auf etwa KZT 40-43 Millionen Jahresumsatz (von zuvor rund KZT 73-75 Millionen) -- Unternehmen nahe der alten Schwelle sollten erneut prüfen, ob sie nun zur Registrierung und damit zur E-Rechnungsstellung verpflichtet sind.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Überprüfen Sie die aktuelle IS-ESF-Portaldomain direkt beim Staatlichen Einnahmenkomitee', 'Suchergebnisse zur IS-ESF-Plattform lieferten neben der echten Domain auch widersprüchliche/inoffizielle Domains -- bestätigen Sie die korrekte aktuelle Anmelde-URL über den eigenen E-Rechnungsbereich von kgd.gov.kz und nicht über ein Suchergebnis, bevor Sie irgendwelche Zugangsdaten verbinden.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Staatliches Einnahmenkomitee -- Abschnitt Elektronische Rechnungen (IS ESF)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KZ' AND pt.sort_order = 0;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-voluntary-2014', 'de',
  'Freiwillige E-Rechnungsstellung startet (ИС ЭСФ)',
  'Das elektronische Rechnungsinformationssystem Kasachstans (ИС ЭСФ) ging am 1. Juli 2014 auf rein freiwilliger Basis in Betrieb, gemäß dem Regierungsbeschluss Nr. 818 (23. Juli 2014), der die ursprünglichen Regeln für Format, Ausstellung, Übermittlung, Empfang, Registrierung und Aufbewahrung elektronischer Rechnungen festlegte. Dies baute auf Artikel 263 des damals geltenden Steuergesetzbuchs von 2008 auf und markierte den Beginn einer Einführung, die erst fünf Jahre später verpflichtend werden sollte.',
  '["In dieser Phase ist keine Maßnahme erforderlich -- die Teilnahme war freiwillig.","Unternehmen, die frühzeitig starten wollten, konnten sich freiwillig über das Staatliche Einnahmenkomitee (kgd.gov.kz) registrieren."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-b2b-mandatory-2019', 'de',
  'E-Rechnungsstellung wird für alle Mehrwertsteuerpflichtigen verpflichtend',
  'Seit dem 1. Januar 2019 ist jeder mehrwertsteuerpflichtige Steuerpflichtige in Kasachstan verpflichtet, für den Verkauf von Waren, Arbeiten und Dienstleistungen elektronische Rechnungen auszustellen, gemäß dem Steuergesetzbuch von 2017 (Gesetz Nr. 120-VI), umgesetzt durch den Erlass Nr. 370 (22. April 2019, rückwirkend zum 1. Januar 2019 angewandt). Kasachstan betreibt ein Echtzeit-Vorabvalidierungsmodell (Clearance): Jede Rechnung wird bei der zentralen IS-ESF-Plattform eingereicht und von dieser validiert, bevor sie für den Käufer sichtbar wird -- vergleichbar mit den Clearance-Systemen Kolumbiens und Argentiniens.',
  '["Registrieren Sie sich für den Zugang zu IS ESF und beschaffen Sie ein digitales Zertifikat der Nationalen Zertifizierungsstelle (NUC RK).","Bestätigen Sie, dass Ihre Rechnungssoftware jede Verkaufsrechnung vor der Zustellung an den Käufer zur Vorabvalidierung bei IS ESF einreicht.","Bewahren Sie validierte Rechnungen und deren IS-ESF-Annahmevermerk gemäß den kasachischen Aufbewahrungsvorschriften auf."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-newtaxcode-2025', 'de',
  'Neues Steuergesetzbuch tritt in Kraft',
  'Das Gesetz Nr. 214-VIII (unterzeichnet am 18. Juli 2025) erließ ein vollständig neues Steuergesetzbuch, das am 1. Januar 2026 in Kraft trat und das Steuergesetzbuch von 2017 (Nr. 120-VI) ersetzt, unter dem die E-Rechnungspflicht von 2019 gegolten hatte. Das neue Gesetzbuch kodifiziert die E-Rechnungspflicht in den Artikeln 207-209 neu und bildet die gesetzliche Grundlage für die Ausweitung des Anwendungsbereichs und die Absenkung der MwSt-Schwelle, die am 1. Januar 2026 folgen. Hinweis: Diese Quelle ist eine Spiegel-Website für Gesetzestexte, nicht direkt adilet.zan.kz -- adilet.zan.kz blockierte in dieser Sitzung den automatisierten Abruf dieser Seite und sollte direkt geprüft werden, bevor die Quellenangabe als vollständig primärquellenverifiziert behandelt wird.',
  '["Prüfen Sie die Artikel 207-209 des neuen Steuergesetzbuchs auf die neu kodifizierten E-Rechnungskategorien vor dem Inkrafttreten am 1. Januar 2026."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-order629-2025', 'de',
  'Neues E-Rechnungsformular und neue Vorschriften genehmigt (Erlass Nr. 629)',
  'Der Erlass Nr. 629 des Finanzministers (28. Oktober 2025) genehmigte ein neues E-Rechnungsformular und ein neues Regelwerk, das den Erlass Nr. 370 ersetzt und zusammen mit dem neuen Steuergesetzbuch am 1. Januar 2026 in Kraft tritt. Er fügt neue Rechnungsfelder hinzu (MwSt-Registrierungsdatum, Codes des Nationalen Produktkatalogs, Kategorien für Anwalts-/gebietsfremde Lieferanten), verlangt eine biometrische ID für die Registrierung und führt eine verpflichtende Käuferbestätigung für korrigierte oder stornierte Rechnungen ein. Die Angaben stammen aus zwei unabhängigen sekundären Branchenwebsites (acsour.kz, pro1c.kz), die in Erlassnummer und Datum übereinstimmen; die entsprechende primäre Adilet-Seite konnte in dieser Sitzung nicht unabhängig abgerufen werden und sollte vor weiterer Verwendung direkt verifiziert werden.',
  '["Aktualisieren Sie die Rechnungssoftware vor dem 1. Januar 2026 im Hinblick auf die neuen Pflichtfelder und den Käuferbestätigungs-Workflow, die durch den Erlass Nr. 629 eingeführt werden."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-scope-expansion-2026', 'de',
  'Mandat wird ausgeweitet: universelle Erfassung mehrwertsteuerpflichtiger Personen plus 12 nicht-mehrwertsteuerpflichtige Kategorien',
  'Ab dem 1. Januar 2026 bestätigen die Artikel 207-209 des neuen Steuergesetzbuchs die universelle E-Rechnungspflicht für alle mehrwertsteuerpflichtigen Steuerpflichtigen und weiten die Pflicht auf rund ein Dutzend nicht mehrwertsteuerpflichtig registrierte Kategorien aus -- Kommissionäre und Spediteure, Zollvertreter und Frachtführer, Steuerpflichtige im vereinfachten Steuerregime, medizinische/pharmazeutische Verkäufer, Anwaltskanzleien, Importeure sowie Teilnehmer am Rückverfolgbarkeitsmodul „Virtuelles Lager", unter anderem. Dies fällt zusammen mit einer gesenkten MwSt-Registrierungsschwelle (10.000 MRP, etwa KZT 40-43 Millionen Jahresumsatz, gegenüber zuvor rund 20.000 MRP) und einer Erhöhung des Regel-MwSt-Satzes auf 16 %, wodurch sich beide Maßnahmen indirekt auf den nun von der E-Rechnungspflicht erfassten Personenkreis auswirken.',
  '["Nicht mehrwertsteuerpflichtig registrierte Unternehmen: Prüfen Sie die Kategorien nach Art. 208 des neuen Steuergesetzbuchs, um festzustellen, ob Ihre Tätigkeit (Kommission/Spedition, Zolldienstleistungen, vereinfachtes Regime, medizinische/pharmazeutische Verkäufe, Rechtsdienstleistungen, Importe, erfasste Waren) nun eine E-Rechnungspflicht auslöst.","Überprüfen Sie erneut Ihren MwSt-Registrierungsstatus anhand der neuen, niedrigeren Schwelle von 10.000 MRP für 2026."]'
);

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr',
  'Régime mature de dédouanement centralisé (CTC) : la facturation électronique B2B obligatoire est en vigueur depuis 2019 via la plateforme étatique IS ESF, étendue à la couverture universelle des assujettis à la TVA et à 12 catégories de non-assujettis à partir du 1er janvier 2026 en vertu d''un Code fiscal entièrement nouveau',
  'Cette page d''analyse reflète les dispositions du Code fiscal du Kazakhstan et ses arrêtés d''application, telles que confirmées via le site propre du Comité des recettes de l''État (kgd.gov.kz) et la base de données juridique Adilet, complétées par des sources secondaires/sectorielles réputées lorsque les pages primaires n''ont pas pu être récupérées de manière indépendante, à la date de début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences actuelles directement auprès du Comité des recettes de l''État du Kazakhstan, des canaux d''assistance propres à la plateforme IS ESF, ou d''un conseiller fiscal/juridique kazakh avant de fonder vos décisions de conformité sur cette page.',
  'Le système IS ESF du Kazakhstan (Système d''information des factures électroniques) a été lancé le 1er juillet 2014 sur une base purement volontaire. Il est devenu obligatoire pour tous les contribuables assujettis à la TVA à partir du 1er janvier 2019, en vertu du Code fiscal de 2017 mis en œuvre par l''arrêté n° 370. Un Code fiscal entièrement nouveau (loi n° 214-VIII, signée le 18 juillet 2025) est entré en vigueur le 1er janvier 2026, recodifiant l''obligation et l''étendant à environ une douzaine de catégories de non-assujettis à la TVA, avec un abaissement du seuil d''immatriculation à la TVA et une augmentation du taux normal de TVA.',
  'Une facture électronique kazakhe conforme est un fichier XML structuré, soumis exclusivement via la plateforme étatique IS ESF sous une signature électronique qualifiée délivrée par une Autorité nationale de certification agréée (NUC RK). La transmission suit un modèle de dédouanement par prévalidation en temps réel (CTC) : chaque facture est soumise à IS ESF et validée par celui-ci, recevant un numéro d''enregistrement unique, avant de devenir visible et valide pour l''acheteur -- l''échange direct de pair à pair en dehors d''IS ESF n''est pas autorisé.',
  'L''obligation de facturation électronique s''applique à tout contribuable assujetti à la TVA, ainsi qu''à (à compter du 1er janvier 2026) environ une douzaine de catégories spécifiquement énumérées de non-assujettis à la TVA, notamment les agents commissionnaires et les transitaires, les représentants en douane et les transporteurs, les contribuables sous régime fiscal simplifié, les vendeurs médicaux et pharmaceutiques, les cabinets d''avocats, les importateurs, et les participants au module de traçabilité des marchandises « Entrepôt virtuel ». Il n''existe aucun seuil de chiffre d''affaires sur l''obligation de facturation électronique elle-même, bien que le seuil d''immatriculation à la TVA, qui détermine indirectement qui devient assujetti à la TVA, ait été abaissé à 10 000 MRP (environ 40-43 millions de KZT de chiffre d''affaires annuel) pour 2026.',
  'La plupart des entreprises assujetties à la TVA qui commercent au Kazakhstan ont déjà une obligation active de facturation électronique via IS ESF -- l''obligation centrale est en vigueur depuis 2019. Le chantier le plus récent est l''extension du champ d''application au 1er janvier 2026 : les catégories de non-assujettis nouvellement couvertes devraient vérifier si leur activité requiert désormais la facturation électronique, et tous les assujettis à la TVA devraient vérifier leur statut d''immatriculation au regard du nouveau seuil abaissé de 10 000 MRP et se préparer aux nouveaux champs de facture et au flux de confirmation de l''acheteur introduits par l''arrêté n° 629.',
  'Le Kazakhstan fait respecter la conformité en matière de facturation électronique par le biais de l''article 280-1 du Code des infractions administratives, avec des amendes échelonnées selon la taille de l''entreprise et le statut de récidive ; un mécanisme distinct de crédit de TVA de 2026 rend par ailleurs la TVA récupérable uniquement lorsque la facture électronique sous-jacente est activement confirmée au sein d''IS ESF avant le dépôt de la déclaration de TVA.',
  'Le Kazakhstan impose la facturation électronique à tous les contribuables assujettis à la TVA depuis le 1er janvier 2019, via la plateforme étatique de dédouanement IS ESF. À compter du 1er janvier 2026, un Code fiscal entièrement nouveau a étendu l''obligation à environ une douzaine de catégories de non-assujettis à la TVA (agents commissionnaires, représentants en douane, vendeurs médicaux/pharmaceutiques, cabinets d''avocats, importateurs, et plus encore), avec un abaissement du seuil d''immatriculation à la TVA (10 000 MRP) et une augmentation du taux normal de TVA (16 %). Un mécanisme distinct de 2026 lie l''éligibilité au crédit de TVA directement à la confirmation active de la facture électronique au sein d''IS ESF.',
  '🇰🇿'
FROM countries WHERE code = 'KZ';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2019', 'La facturation électronique devient obligatoire pour tous les contribuables assujettis à la TVA' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2026', 'L''obligation s''étend à environ 12 catégories de non-assujettis à la TVA en vertu du nouveau Code fiscal' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '10 000 MRP', 'Nouveau seuil d''immatriculation à la TVA pour 2026 (~40-43 millions de KZT de chiffre d''affaires), contre ~20 000 MRP auparavant' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '16 %', 'Nouveau taux normal de TVA à compter de 2026, contre 12 % auparavant' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '2014', 'IS ESF est lancé comme projet pilote volontaire -- 12 ans d''histoire au moment de l''extension de 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KZ' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et modèle de transmission', '[["Format de facture", "XML structuré, soumis exclusivement via la plateforme étatique IS ESF"], ["Modèle de transmission", "Dédouanement par prévalidation en temps réel (CTC) -- IS ESF valide et attribue un numéro d''enregistrement avant que la facture n''atteigne l''acheteur"], ["Signature numérique", "Signature électronique qualifiée via un certificat d''une Autorité nationale de certification agréée (NUC RK)"], ["Échange de pair à pair", "Non autorisé -- chaque facture doit transiter par IS ESF"]]', 'La question de savoir si IS ESF n''accepte que le XML, sans format alternatif, provient uniquement d''une note secondaire résumée par IA au cours de cette phase de recherche, non recoupée de manière indépendante avec le texte primaire de l''arrêté n° 629/du Code fiscal -- à considérer comme plausible, non confirmé.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Évolution du cadre juridique', '[["2014-2018", "Règles volontaires en vertu des résolutions gouvernementales n° 818 et n° 573, puis de l''arrêté n° 270 sous le Code fiscal de 2018"], ["2019-2025", "L''arrêté n° 370 (22 avril 2019, rétroactif au 1er janvier 2019) régit l''ère obligatoire, modifié à plusieurs reprises par l''arrêté n° 1321 (26 décembre 2023)"], ["À partir de 2026", "Le nouveau Code fiscal (loi n° 214-VIII) ainsi que l''arrêté n° 629 (28 octobre 2025) remplacent entièrement le cadre antérieur"]]', 'La page exacte de la base de données juridique Adilet relative à l''arrêté n° 629 n''a pas pu être récupérée de manière indépendante au cours de cette phase de recherche (erreurs robots/SSL à chaque tentative) -- son numéro et sa date sont corroborés par deux sources sectorielles secondaires indépendantes, mais une vérification directe de la source primaire reste recommandée.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui doit émettre des factures électroniques', '[["Contribuables assujettis à la TVA", "Exigence universelle depuis le 1er janvier 2019 (Code fiscal de 2017) ; recodifiée à l''art. 207 du nouveau Code fiscal à partir de 2026"], ["Catégories de non-assujettis à la TVA (à partir de 2026)", "~12 catégories relevant des art. 208-209 : agents commissionnaires/transitaires, représentants en douane/transporteurs, contribuables sous régime simplifié, vendeurs médicaux/pharmaceutiques, cabinets d''avocats, importateurs, participants à l''Entrepôt virtuel, et autres"], ["Explicitement exclus", "Particuliers vendant des biens personnels ; praticiens privés/entrepreneurs individuels agissant à ce titre ; la plupart des ventes au détail via caisse enregistreuse (avec exceptions pour les marchandises soumises à accise/importées/répertoriées)"], ["Seuil de chiffre d''affaires", "Aucun pour l''obligation de facturation électronique elle-même, mais le seuil sous-jacent d''immatriculation à la TVA est passé à 10 000 MRP pour 2026"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux de dédouanement', 'Une facture conforme à IS ESF suit la séquence suivante :', 'Seule une facture qu''IS ESF a validée et à laquelle il a attribué un numéro d''enregistrement est juridiquement valable pour l''acheteur -- une remise directe en dehors de la plateforme n''a aucun effet.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Générer le XML structuré et apposer une signature numérique qualifiée NUC RK' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Soumettre à la plateforme étatique IS ESF pour prévalidation' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'IS ESF valide la structure et le contenu, et attribue un numéro d''enregistrement unique' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'La facture validée devient visible et juridiquement valable pour l''acheteur' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'À partir de 2026 : l''éligibilité de l''acheteur au crédit de TVA dépend de la confirmation active de la facture au sein d''IS ESF avant le dépôt de la déclaration de TVA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KZ' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚠️ Sanctions au titre de l''article 280-1 du Code des infractions administratives', NULL, NULL, 'Le Kazakhstan sanctionne les infractions à la facturation électronique en vertu de l''article 280-1 du Code des infractions administratives (code de base : loi n° 235-V, 5 juillet 2014). Un premier manquement à l''émission ou une émission tardive entraîne un avertissement ; les infractions répétées dans l''année entraînent des amendes échelonnées selon la taille de l''entreprise -- environ 40-150 MRP en cas de non-émission répétée (petite/moyenne/grande entreprise), et 20-100 MRP en cas d''émission tardive répétée. L''absence des documents d''exportation devant accompagner la facture entraîne une amende forfaitaire de 50 MRP en première infraction, 100 MRP en cas de récidive. À la valeur du MRP de 2026 (4 325 KZT), une amende de 40 MRP pour une petite entreprise équivaut à environ 173 000 KZT. Ces chiffres sont corroborés par deux sites agrégateurs juridiques secondaires indépendants à la structure concordante, mais aucun n''est le texte statutaire primaire propre d''Adilet au Kazakhstan -- à considérer comme plausibles dans l''attente d''une vérification directe.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '💳 Crédit de TVA lié à la confirmation de la facture électronique', NULL, NULL, 'À partir de 2026, un nouveau mécanisme lierait, selon certaines sources, l''éligibilité au crédit de TVA directement au respect de la facturation électronique : la TVA en amont ne peut être créditée que lorsque la facture électronique concernée est activement confirmée au sein d''IS ESF avant le dépôt de la déclaration de TVA. Par ailleurs, une source secondaire décrit un autre mécanisme de mise en application pour 2026 permettant la suspension temporaire de l''accès d''un contribuable à IS ESF en cas de notifications système non traitées, ce qui bloquerait en pratique entièrement la facturation -- ce mécanisme de suspension n''est pas confirmé de manière indépendante par une citation primaire du Code fiscal et doit être considéré comme non vérifié.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔍 Ce que nous n''avons pas pu confirmer', NULL, NULL, 'Quatre points sont signalés à l''issue de cette phase de recherche plutôt que présentés comme des faits établis : (1) le domaine exact et actuel du portail public IS ESF -- les résultats de recherche ont fait apparaître à la fois une référence « esf.gov.kz » et ce qui semble être un domaine clone de phishing sans rapport, de sorte qu''aucune URL de portail non vérifiée n''est citée sur cette page ; (2) si IS ESF n''accepte véritablement que le XML, sans format alternatif, information provenant uniquement d''un briefing résumé par IA ; (3) les délais exacts d''émission en nombre de jours et l''exception de facture papier en cas de panne du système, avec la même réserve de source unique ; (4) l''existence éventuelle d''une vague distincte, datée séparément, de facturation électronique obligatoire pour les « marchandises à risque » antérieure à 2019, précédant l''obligation générale de 2019 -- aucune date obtenue de manière indépendante n''a pu être trouvée à ce sujet, de sorte qu''aucun jalon de ce type n''est inclus sur cette page.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KZ' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Confirmez votre statut d''assujetti à la TVA et votre inscription à IS ESF', 'La facturation électronique est obligatoire pour tous les contribuables assujettis à la TVA au Kazakhstan depuis le 1er janvier 2019 -- vérifiez que votre entreprise est inscrite pour l''accès à IS ESF et détient un certificat numérique NUC RK valide.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Si vous n''êtes pas assujetti à la TVA, vérifiez les catégories de non-assujettis du nouveau Code fiscal', 'À compter du 1er janvier 2026, environ une douzaine de catégories non immatriculées à la TVA (agents commissionnaires/transitaires, représentants en douane, contribuables sous régime simplifié, vendeurs médicaux/pharmaceutiques, cabinets d''avocats, importateurs, et autres) doivent également émettre des factures électroniques -- consultez les articles 208-209 pour savoir si votre activité relève désormais du champ d''application.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Mettez à jour le logiciel de facturation pour les nouveaux champs et le flux de confirmation de l''acheteur de l''arrêté n° 629', 'Le nouveau formulaire de facture électronique et les nouvelles règles, en vigueur à compter du 1er janvier 2026, ajoutent des champs (date d''immatriculation à la TVA, codes du Catalogue national des produits, catégories de fournisseurs avocats/non-résidents) et exigent une confirmation obligatoire de l''acheteur pour les factures corrigées ou annulées.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez à nouveau votre immatriculation à la TVA au regard du seuil abaissé de 10 000 MRP', 'Le seuil d''immatriculation à la TVA pour 2026 est tombé à environ 40-43 millions de KZT de chiffre d''affaires annuel (contre environ 73-75 millions de KZT auparavant) -- les entreprises proches de l''ancien seuil devraient vérifier à nouveau si elles sont désormais tenues de s''immatriculer, et donc de facturer électroniquement.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez le domaine actuel du portail IS ESF directement auprès du Comité des recettes de l''État', 'Les résultats de recherche relatifs à la plateforme IS ESF ont fait apparaître des domaines contradictoires/non officiels aux côtés du domaine authentique -- confirmez l''URL de connexion actuelle correcte via la section dédiée à la facturation électronique du site kgd.gov.kz lui-même, plutôt qu''un résultat de recherche, avant de connecter tout identifiant.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KZ' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Comité des recettes de l''État -- section Factures électroniques (IS ESF)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KZ' AND pt.sort_order = 0;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-voluntary-2014', 'fr',
  'Lancement de la facturation électronique volontaire (ИС ЭСФ)',
  'Le système d''information des factures électroniques du Kazakhstan (ИС ЭСФ) est entré en service le 1er juillet 2014 sur une base purement volontaire, en vertu de la Résolution gouvernementale n° 818 (23 juillet 2014), qui a fixé les règles initiales de format, d''émission, de transmission, de réception, d''enregistrement et de conservation des factures électroniques. Cette mesure s''appuyait sur l''article 263 du Code fiscal de 2008 alors en vigueur et a marqué le début d''un déploiement qui ne deviendrait obligatoire que cinq ans plus tard.',
  '["Aucune action requise à ce stade -- la participation était facultative.","Les entreprises souhaitant prendre une longueur d''avance pouvaient s''inscrire volontairement auprès du Comité des recettes de l''État (kgd.gov.kz)."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-b2b-mandatory-2019', 'fr',
  'La facturation électronique devient obligatoire pour tous les assujettis à la TVA',
  'Depuis le 1er janvier 2019, tout contribuable assujetti à la TVA au Kazakhstan est tenu d''émettre des factures électroniques pour la vente de biens, de travaux et de services, en vertu du Code fiscal de 2017 (loi n° 120-VI), mis en œuvre par l''arrêté n° 370 (22 avril 2019, appliqué rétroactivement au 1er janvier 2019). Le Kazakhstan applique un modèle de dédouanement par prévalidation en temps réel : chaque facture est soumise à la plateforme centrale IS ESF et validée par celle-ci avant de devenir visible pour l''acheteur, comparable aux systèmes de dédouanement utilisés en Colombie et en Argentine.',
  '["Inscrivez-vous pour obtenir l''accès à IS ESF et procurez-vous un certificat numérique de l''Autorité nationale de certification (NUC RK).","Vérifiez que votre logiciel de facturation soumet chaque facture de vente à IS ESF pour prévalidation avant sa remise à l''acheteur.","Conservez les factures validées et leur enregistrement d''acceptation IS ESF conformément aux règles de conservation documentaire du Kazakhstan."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-newtaxcode-2025', 'fr',
  'Le nouveau Code fiscal est promulgué',
  'La loi n° 214-VIII (signée le 18 juillet 2025) a instauré un Code fiscal entièrement nouveau, entré en vigueur le 1er janvier 2026, remplaçant le Code fiscal de 2017 (n° 120-VI) sous lequel l''obligation de facturation électronique de 2019 avait fonctionné. Le nouveau code recodifie l''obligation de facturation électronique aux articles 207-209 et constitue le véhicule législatif de l''extension du champ d''application et de l''abaissement du seuil de TVA qui suivent au 1er janvier 2026. Remarque : cette source est un site miroir de textes juridiques, non directement adilet.zan.kz -- adilet.zan.kz a bloqué la récupération automatisée de cette page au cours de cette session et devrait être consulté directement avant de considérer la citation comme pleinement vérifiée en tant que source primaire.',
  '["Examinez les articles 207-209 du nouveau Code fiscal pour connaître les catégories recodifiées de facturation électronique avant l''entrée en vigueur du 1er janvier 2026."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-order629-2025', 'fr',
  'Nouveau formulaire de facture électronique et nouvelles règles approuvés (arrêté n° 629)',
  'L''arrêté n° 629 du ministre des Finances (28 octobre 2025) a approuvé un nouveau formulaire de facture électronique et un nouveau corpus de règles, remplaçant l''arrêté n° 370 et entrant en vigueur le 1er janvier 2026 en même temps que le nouveau Code fiscal. Il ajoute de nouveaux champs à la facture (date d''immatriculation à la TVA, codes du Catalogue national des produits, catégories de fournisseurs avocats/non-résidents), exige une identification biométrique pour l''inscription et introduit une confirmation obligatoire de l''acheteur pour les factures corrigées ou annulées. Ces informations proviennent de deux sites sectoriels secondaires indépendants (acsour.kz, pro1c.kz) qui s''accordent sur le numéro et la date de l''arrêté ; la page Adilet correspondante, en tant que source primaire, n''a pas pu être récupérée de manière indépendante au cours de cette session et devrait être vérifiée directement avant toute confiance accrue.',
  '["Mettez à jour le logiciel de facturation avant le 1er janvier 2026 pour tenir compte des nouveaux champs obligatoires et du flux de confirmation de l''acheteur introduits par l''arrêté n° 629."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'kz-scope-expansion-2026', 'fr',
  'L''obligation s''étend : couverture universelle des assujettis à la TVA et 12 catégories de non-assujettis',
  'À compter du 1er janvier 2026, les articles 207-209 du nouveau Code fiscal confirment la couverture universelle de la facturation électronique pour tous les assujettis à la TVA et étendent l''obligation à environ une douzaine de catégories non immatriculées à la TVA -- agents commissionnaires et transitaires, représentants en douane et transporteurs, contribuables sous régime fiscal simplifié, vendeurs médicaux/pharmaceutiques, cabinets d''avocats, importateurs et participants au module de traçabilité « Entrepôt virtuel », entre autres. Cette mesure s''accompagne d''un abaissement du seuil d''immatriculation à la TVA (10 000 MRP, soit environ 40-43 millions de KZT de chiffre d''affaires annuel, contre environ 20 000 MRP auparavant) et d''une augmentation du taux normal de TVA à 16 %, deux facteurs qui élargissent indirectement la population désormais soumise à la facturation électronique.',
  '["Entreprises non immatriculées à la TVA : vérifiez les catégories de l''art. 208 du nouveau Code fiscal pour savoir si votre activité (commission/transit, services douaniers, régime simplifié, ventes médicales/pharmaceutiques, services juridiques, importations, marchandises tracées) requiert désormais la facturation électronique.","Vérifiez à nouveau votre statut d''immatriculation à la TVA au regard du nouveau seuil, abaissé à 10 000 MRP pour 2026."]'
);
